12. 다음 treetest() 함수로 만들어지는 트리의 유형은?
typedef struct treeNode {
int data;
struct treeNode *left, *right;
} treeNode;
void treetest() {
treeNode n1 = { 12, NULL, NULL };
treeNode n2 = { 33, NULL, NULL };
treeNode n3 = { 21, &n1, &n2 };
treeNode n4 = { 74, NULL, NULL };
treeNode n5 = { 67, NULL, &n4 };
treeNode n6 = { 59, NULL, &n5 };
treeNode n7 = { 46, &n3, &n6 };
treeNode* root = &n7;
}
①스레드 이진 트리(threaded binary tree)
②완전 이진 트리(complete binary tree)
③이진 탐색 트리(binary search tree)
④포화 이진 트리(full binary tree)

15. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
void func(int *array, int size) {
int *p = array;
*p = 100;
*(p + 2) = 100;
p = p + 1;
}
int main(int argc, char *argv[]) {
int array[5] = { 2, 4, 6, 8, 10 };
func(array, 5);
for(int i = 0; i < 5; i++)
printf("%d ", array[i]);
printf("\n");
return 0;
}
①100 4 6 8 100
②100 4 6 100 10
③100 4 100 8 10
④100 100 68 8 10

17. 다음 C 코드에 10개의 노드로 이루어진 이중 연결 리스트를 입력하여
수행한 후, 이중 연결 리스트에 남아 있는 노드의 개수는? (단, 10개
노드 입력 후 수행 시 start는 첫 번째 노드를 가리킨다)
typedef struct node {
int key;
struct node *prev, *next;
} node;
void foobar(node *start) {
node *current = start;
int iseven = 0;
while(current != NULL) {
if(iseven == 1) {
current->prev->next = current->next;
if(current->next != NULL)
current->next->prev = current->prev;
}
current = current->next;
iseven = 1 - iseven;
}
}
①5
②6
③8
④10

20. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
typedef struct stack {
int data[10]; int top;
} stack;
stack s1, s2;
void push(stack *ss, int i) {
ss->top = ss->top + 1;
ss->data[ss->top] = i;
}
int pop(stack *ss) {
return ss->data[ss->top--];
}
int size(stack *ss) {
return ((ss->top) + 1);
}
void push2(int n) {
push(&s1, n);
}
int pop2() {
if(size(&s2) == 0) {
int s = size(&s1);
for(int i = 0; i < s; i++)
push(&s2, pop(&s1));
}
return pop(&s2);
}
int main(int argc, char **argv) {
s1.top = s2.top = -1;
push2(1);  push2(2);  push2(3);
printf("%d  ", pop2());
printf("%d  ", pop2());
push2(4);  push2(5);
printf("%d  ", pop2());
printf("%d  ", pop2());
printf("%d  ", pop2());
return 0;
}
①1 2 3 4 5
②2 1 5 4 3
③3 2 5 4 1
④5 4 3 2 1
